import { plainDate, plainDateToString } from '@absoluteui/core';
import { DatePicker, type DatePickerChangeDetail } from '@absoluteui/components/date-picker';

const host = document.createElement('div');
document.body.append(host);
DatePicker.create(host, { label: 'Check-in', name: 'checkIn', required: true, min: plainDate(2026, 1, 1), max: plainDate(2026, 12, 31) });
host.addEventListener('aui-change', (event) => {
  const { value, validity } = (event as CustomEvent<DatePickerChangeDetail>).detail;
  host.dataset.value = value && validity.valid ? plainDateToString(value) : '';
});

import { dayOfWeek } from '@absoluteui/core';
import { DatePicker } from '@absoluteui/components/date-picker';

const host = document.createElement('div');
document.body.append(host);
DatePicker.create(host, { label: 'Delivery date', firstDayOfWeek: 1, isDateDisabled: (date) => dayOfWeek(date) === 7 });
